-- ============================================================
-- CAREER_COURSES
-- Cada carrera hereda los cursos del área a la que pertenece.
-- Un estudiante que postula a Medicina (Área A de UNMSM) estudia los
-- mismos cursos que evalúa el examen de esa área.
-- ============================================================
INSERT INTO career_courses (career_id, course_id)
SELECT c.id, ac.course_id
FROM careers c
JOIN area_courses ac ON ac.area_id = c.area_id
ON CONFLICT (career_id, course_id) DO NOTHING;
